/**
 * LOINC lab tests beyond the curated biomarker catalog: every active numeric
 * lab observation with example units, generated by `scripts/loinc-update.mjs`.
 * The list is large, so it loads only when first needed (searching for a test
 * or importing a report), never at startup. It has names, codes and units but
 * no reference ranges: those come from the user's own lab report.
 *
 * This material contains content from LOINC (http://loinc.org). See
 * `LOINC_short_license.txt` next to this file.
 */
import {
  EMPTY_BIOMARKER_EDUCATION,
  type RecordableBiomarker,
  type UnitOption,
} from '@/src/data/biomarkers';

import type { LoincLabTestRow } from './loincLabTests';

export interface LoincLabTests {
  /** Finds a test by its LOINC code. */
  get: (loinc: string) => RecordableBiomarker | undefined;
  /** Tests whose name has every word of the query, or whose code matches; most common first. */
  search: (query: string, limit?: number) => RecordableBiomarker[];
}

export const LOINC_CODE_PATTERN = /^\d{1,7}-\d$/;
const SEARCH_LIMIT = 50;

/** A readable label for a UCUM unit, written the way the catalog writes them. */
export function ucumLabel(ucum: string): string {
  if (/^\{[^}]+\}$/.test(ucum)) return ucum.slice(1, -1);
  return ucum
    .replace("[arb'U]", 'AU')
    .replace('{1.73_m2}', '1.73m2')
    .replace(/\{[^}]*\}/g, '')
    .replace(/[[\]]/g, '');
}

/**
 * A recordable biomarker for a LOINC test outside the catalog. Its units
 * don't convert into each other, and it has no catalog reference range.
 */
export function loincTestBiomarker(
  loinc: string,
  name: string,
  units: UnitOption[]
): RecordableBiomarker {
  return {
    id: loinc,
    name,
    aliases: [],
    loinc,
    category: 'Other',
    primaryUnit: units[0]?.label ?? '',
    ucumCode: units[0]?.ucum ?? '',
    units,
    description: name,
    education: { ...EMPTY_BIOMARKER_EDUCATION },
  };
}

function toBiomarker([loinc, name, units]: LoincLabTestRow) {
  return loincTestBiomarker(
    loinc,
    name,
    units.split(';').map((ucum) => ({ label: ucumLabel(ucum), ucum }))
  );
}

function indexTests(rows: LoincLabTestRow[]): LoincLabTests {
  const byCode = new Map(rows.map((row) => [row[0], row]));
  const names = rows.map(([, name]) => name.toLowerCase());
  return {
    get: (loinc) => {
      const row = byCode.get(loinc.trim());
      return row && toBiomarker(row);
    },
    search: (query, limit = SEARCH_LIMIT) => {
      const clean = query.trim().toLowerCase();
      if (!clean) return [];
      const words = clean.split(/\s+/);
      const matches: RecordableBiomarker[] = [];
      for (let i = 0; i < rows.length && matches.length < limit; i++) {
        if (
          rows[i][0].startsWith(clean) ||
          words.every((word) => names[i].includes(word))
        )
          matches.push(toBiomarker(rows[i]));
      }
      return matches;
    },
  };
}

let loading: Promise<LoincLabTests> | undefined;

/** Loads the LOINC lab test list once; later calls share the same load. */
export function loadLoincLabTests(): Promise<LoincLabTests> {
  loading ??= import('./loincLabTests')
    .then((module) => indexTests(module.LOINC_LAB_TESTS))
    .catch((error) => {
      loading = undefined;
      throw error;
    });
  return loading;
}
